#!/usr/bin/env python3
"""Verification for the config_issues.rs -> config_issues/ split. (unique: ci-20260809)"""
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path("/home/watermarkhu/repositories/mlt")
SRC = ROOT / "crates/mlt_rules/src"
ORIG = SRC / "config_issues.rs"
NEW_DIR = SRC / "config_issues"

fails = []


def extract_method(path, name):
    text = path.read_text()
    pat = re.compile(r"(?m)^(?:    pub\(crate\) fn |    fn )" + re.escape(name) + r"\(")
    m = pat.search(text)
    if not m:
        return None
    start = m.start()
    brace_start = text.index("{", start)
    depth = 0
    for i in range(brace_start, len(text)):
        if text[i] == "{":
            depth += 1
        elif text[i] == "}":
            depth -= 1
            if depth == 0:
                return text[start : i + 1]
    return None


print("=" * 70)
print("1. Method body diffs (original vs moved; normalized pub(crate) fn)")
print("=" * 70)
checks = ["check_bdcfg", "check_cferr", "check_bdopt", "check_cfig"]
for name in checks:
    orig_body = extract_method(ORIG, name)
    new_body = extract_method(NEW_DIR / f"{name}.rs", name)
    if orig_body is None:
        fails.append(f"{name}: not found in original")
        print(f"[FAIL] {name}: not found in original")
        continue
    if new_body is None:
        fails.append(f"{name}: not found in moved file")
        print(f"[FAIL] {name}: not found in moved file")
        continue
    normalized = new_body.replace("pub(crate) fn ", "fn ", 1)
    if orig_body == normalized:
        print(f"[OK]   {name}: body identical (only `fn` -> `pub(crate) fn`)")
    else:
        fails.append(f"{name}: body differs from original")
        print(f"[FAIL] {name}: body differs from original")
        import difflib

        for line in difflib.unified_diff(
            orig_body.splitlines(), normalized.splitlines(), "orig", "moved", lineterm=""
        ):
            print(line)

print()
print("=" * 70)
print("2. Each check ID owned by exactly one file across config_issues/")
print("=" * 70)
from collections import defaultdict

owner = defaultdict(set)
for p in sorted(NEW_DIR.rglob("*.rs")):
    for cid in re.findall(r'rule_id: "([A-Z]+)"', p.read_text()):
        owner[cid].add(p.name)
expected = {
    "BDCFG": "check_bdcfg.rs",
    "CFERR": "check_cferr.rs",
    "BDOPT": "check_bdopt.rs",
    "CFIG": "check_cfig.rs",
}
for cid, want_file in expected.items():
    if list(owner.get(cid, [])) == [want_file]:
        print(f"[OK]   {cid}: all rule_id assignments in {want_file} only")
    else:
        fails.append(f"{cid}: rule_id assignments not confined to {want_file}: {owner.get(cid)}")
        print(f"[FAIL] {cid}: rule_id assignments in {owner.get(cid)} (expected only {want_file})")
for cid, want_file in expected.items():
    for p in sorted(NEW_DIR.rglob("*.rs")):
        if p.name == want_file:
            continue
        if cid in re.findall(r'rule_id: "([A-Z]+)"', p.read_text()):
            fails.append(f"{cid} rule_id leaked into {p.name}")

print()
print("=" * 70)
print("3. Dispatch references in mod.rs vs moved check methods")
print("=" * 70)
mod_text = (NEW_DIR / "mod.rs").read_text()
dispatch_names = set(re.findall(r"self\.(check_\w+)\(", mod_text))
moved_names = {f"check_{c}" for c in ["bdcfg", "cferr", "bdopt", "cfig"]}
for n in sorted(moved_names):
    if n in dispatch_names:
        print(f"[OK]   dispatch calls {n}")
    else:
        fails.append(f"dispatch does not call {n}")
        print(f"[FAIL] dispatch does not call {n}")
extra = dispatch_names - moved_names
if extra:
    fails.append(f"dispatch references unexpected methods: {extra}")
for c in ["bdcfg", "cferr", "bdopt", "cfig"]:
    n = (NEW_DIR / f"check_{c}.rs").read_text().count(f"fn check_{c}(")
    if n == 1:
        print(f"[OK]   check_{c} defined exactly once in check_{c}.rs")
    else:
        fails.append(f"check_{c} defined {n}x (expected 1)")

print()
print("=" * 70)
print("4. Test counts (original 9 = 8 moved + 1 kept)")
print("=" * 70)
orig_tests = ORIG.read_text().count("#[test]")
kept_tests = (NEW_DIR / "mod.rs").read_text().count("#[test]")
moved_tests = 0
for c in ["bdcfg", "cferr", "bdopt", "cfig"]:
    n = (NEW_DIR / f"check_{c}.rs").read_text().count("#[test]")
    moved_tests += n
    print(f"[OK]   check_{c}.rs carries {n} tests")
print(f"[OK]   mod.rs keeps {kept_tests} generic test(s)")
